import { mileReceiverFeedback, MILE_RECEIVER_GUIDANCE } from './hundredHandMileReceiverFeedback.js';
import { getPromptDeck } from './promptDeck.js';
const ID='hundred-hand-mile:restoration';
const MILESTONES={survey:'Break surveyed.',recover_power:'Recovered power installed.',restore_guide:'Route guide installed.',deliver_cargo:'Cargo contribution installed.',witness_convoy:'First convoy crossing witnessed.'};
const REFUSALS={
 'source-outside-receiver':'Tow the whole original part into the service capture beside its matching socket.',
 'receiver-speed-too-high':'Slow the part and let its rotation settle inside the socket.',
 'current-native-player-tow-required':'Keep your live Massline attached to the original part.',
 'hold-outside-service-receiver':'Bring your ship close to the service socket and slow to a stop.',
 'unreserved-cargo-required':'Free the required goods in your hold; reserved cargo cannot be contributed.',
 'installation-volume-occupied':'Move ships and loose objects clear of the installation socket.',
 'installation-volume-occupied-or-unknown':'Clear the socket and wait for the physical clearance check.',
 'installation-pending':'Your contribution is committed. Keep the socket clear while it is installed.',
 'stale-revision':'The work order changed. Scan the site again before contributing.',
 'spawn-budget-full':'Traffic is at capacity. Keep flying nearby and request the convoy again shortly.',
 'current-navigability-proof-required':'The route is occupied or its clearance is still being checked.',
 'native-route-changed':'Something entered the route. Clear it before requesting the convoy again.',
 'finite-original-source-unavailable':'The original part is unavailable. No duplicate can be supplied.',
 'two-verified-interventions-required':'The crew record changed. Scan the Mile again to check the work order.',
};
const WORK_FAMILIES = Object.freeze({
 tally: { name: 'Tally Three delivery', action: 'deliver Tally Three freight' },
 ilex: { name: 'Ilex Ark settlement', action: 'finish the Ilex Ark run (any recorded outcome)' },
 towline: { name: 'Towline Table cleanup', action: 'finish one Towline Table cleanup' },
 lastShift: { name: 'Last Shift archive report', action: 'record a Last Shift archive report' },
});
function prerequisiteGuidance(row) {
 const raw = row.evidence?.families;
 // This is a view of the graph's verified families, never a second receipt validator.
 // Unknown/missing data asks for a fresh owner readout, not invented remaining work.
 if (!Array.isArray(raw) || Array.from(raw).some(id => typeof id !== 'string' || !Object.hasOwn(WORK_FAMILIES, id)))
  return 'The crew record needs refreshing. Scan the Mile again to check your work order.';
 const families = [...new Set(raw)];
 const progress = `Recorded: ${families.length} of 2 distinct work families${families.length ? ': ' + families.map(id => WORK_FAMILIES[id].name).join(', ') : ''}.`;
 if (row.lastResult?.ok === false && ['stale-revision', 'two-verified-interventions-required', 'site-unavailable', 'current-site-inspection-required'].includes(row.lastResult.reason))
  return progress + ' Scan the Mile again to refresh the work order.';
 if (families.length >= 2)
  return progress + (row.canAccept ? ' Restore a short working route with recovered parts. Earlier deliveries stay spent.' : ' Return to the Mile and scan again to check the work order.');
 if (row.canAccept) return 'The crew record needs refreshing. Scan the Mile again to check your work order.';
 const remaining = Object.keys(WORK_FAMILIES).filter(id => !families.includes(id)).map(id => WORK_FAMILIES[id].action);
 return progress + (families.length ? ' Choose one other family: ' : ' Any two count: ') + remaining.join('; ') + '.';
}
const LABELS={power:'INSTALL RECOVERED POWER',guide:'INSTALL RECOVERED GUIDE',cargo:'CONTRIBUTE CARGO'};
export const hundredHandMilePrompt={
 name:'hundredHandMilePrompt',
 init(ctx){this.state=ctx.state;this.bus=ctx.bus;this._subs=[ctx.bus.on('hundredHandMile:offer',r=>this.offer(r)),ctx.bus.on('hundredHandMile:milestone',r=>{
  const text=MILESTONES[r?.chapterId];if(text)this.bus.emit('toast',{text:'Hundred-Hand Mile: '+text,kind:'info',ttl:6});
 })];
  for(const event of ['sector:exit','dock:completed','save:restoring'])this._subs.push(ctx.bus.on(event,()=>this.newGame()));},
 offer(row){
  if(!row?.enabled)return false;
  const choices=[],commands=new Map();
  const add=(id,label,command,title)=>{choices.push({id,label,title});commands.set(id,command);};
  let detail=prerequisiteGuidance(row);
  if(row.canAccept && !row.accepted){add('accept','HELP RESTORE THE MILE',{action:'accept',revision:row.revision});}
  else if(row.accepted && !row.abandoned){
   detail=`${row.completedMilestoneIds.length} of 5 milestones recorded. Installed: ${row.installedModuleIds.join(', ')||'none'}.`;
   if(row.crewCompletedModuleIds?.length)detail+=` Crew completed: ${row.crewCompletedModuleIds.join(', ')}. Those repairs earn no player reward.`;
   if(!row.completedMilestoneIds.includes('survey'))add('survey','SURVEY THE BREAK',{action:'survey'});
   else if(row.pendingInstall)detail+=' Installation is waiting for a clear socket.';
   else for(const [moduleId,chapterId] of [['power','recover_power'],['guide','restore_guide'],['cargo','deliver_cargo']]){
    if(row.installedModuleIds.includes(moduleId))continue;
    const repair=row.destroyedModuleIds.includes(moduleId);
    const qty=repair?2:row.cargoRequirement.qty;
    const item=repair||row.cargoRequirement.commodityId==='cmdty_scrap_metal'?'scrap metal':'food';
    let title=repair?`Use 2 scrap metal from your hold to replace the lost ${moduleId}. No second milestone reward.`:moduleId==='cargo'?`Transfer ${qty} ${item} from your hold.`:'Tow the original part into the service capture beside its matching socket at low speed. The crew seats it only when the final socket is clear.';
    const receiver = mileReceiverFeedback(row,moduleId,this.state?.tick);
    title+=' Last check: '+receiver;
    detail+=` ${moduleId[0].toUpperCase()+moduleId.slice(1)}: ${receiver}`;
    add(moduleId,repair?`REPAIR ${moduleId.toUpperCase()} (2 SCRAP)`:moduleId==='cargo'?`CONTRIBUTE ${qty} ${item.toUpperCase()}`:LABELS[moduleId],{action:'contribute',chapterId,revision:row.revision},title);
   }
   if(row.installedModuleIds.includes('power')&&!row.finalConvoyJobId&&!row.finalConvoyOutcome)add('dispatch','REQUEST THE FIRST CONVOY',{action:'dispatch'},'A real traffic hull needs a clear route and available ship budget. Stay nearby to witness its crossing.');
   if(row.finalConvoyJobId&&!row.finalConvoyOutcome)detail+=' First convoy in progress; stay near the route to witness it.';
   if(row.finalConvoyOutcome)detail+=` Convoy: ${row.finalConvoyOutcome}.`;
   if(row.finalConvoyOutcome==='arrived'&&!row.completedMilestoneIds.includes('witness_convoy'))detail+=' Witness milestone not yet recorded. No witness reward paid.';
  }else if(row.abandoned)detail='Restoration left unfinished. Existing contributions remain installed or spent.';
  if(row.lastResult?.ok===false)detail+=' '+(MILE_RECEIVER_GUIDANCE[row.lastResult.reason] || REFUSALS[row.lastResult.reason] || 'The action could not complete. Check the original part, clear socket and live tow; scan again to retry.');
  choices.push({id:'leave',label:'KEEP FLYING',cancel:true});
  return getPromptDeck()?.offerDecision({id:ID,sender:'HUNDRED-HAND MILE · CREW RECORD',kind:'info',headline:'A working route, built from what survived.',detail,choices,
   onChoose:id=>{this.newGame();const command=commands.get(id);if(command)this.bus.emit('hundredHandMile:command',command);}})||false;
 },
 newGame(){getPromptDeck()?.resolveDecision(ID);},
 destroy(){this.newGame();for(const off of this._subs||[])off?.();},
};

