import test from 'node:test';
import assert from 'node:assert/strict';
import {fixture} from './hundred-hand-mile-finite-fixture.mjs';
import {documentAdapter} from './hundred-hand-mile-dom-adapter.mjs';
import {createPromptDeck} from '../src/ui/promptDeck.js';
import {hundredHandMilePrompt} from '../src/ui/hundredHandMilePrompt.js';
import {TALLY_THREE} from '../src/data/tallyThree.js';
import {freshTowlineTable,towlineReceiptId,towlineCleanupId} from '../src/data/towlineTable.js';
import {freshIlexArk,ILEX_ARK,ILEX_VAULT_IDS} from '../src/data/ilexArk.js';
const ID='hundred-hand-mile:restoration';
function harness(){const h=fixture(),doc=documentAdapter();h.state.mode='flight';const deck=createPromptDeck({document:doc,state:h.state,bus:h.bus}),prompt=Object.create(hundredHandMilePrompt),commands=[];prompt.init({state:h.state,bus:h.bus});h.bus.on('hundredHandMile:command',x=>commands.push(x));return {...h,doc,deck,prompt,commands,close(){prompt.destroy();deck.destroy();h.dispose()}};}
function clear(h){delete h.state.salvage.sources[TALLY_THREE.sourceKey];h.state.towlineTable=freshTowlineTable();h.state.ilexArk=freshIlexArk();delete h.state.world.lastShift;}
function snapshot(h){return JSON.stringify({graph:h.graph.serialize(),salvage:h.state.salvage,towline:h.state.towlineTable,ilex:h.state.ilexArk,world:h.state.world,cargo:h.state.player.cargo,credits:h.state.player.credits,economy:h.e.serialize()});}
function show(h,row=h.graph.readout()){const before=snapshot(h),input=JSON.stringify(row);assert.equal(h.prompt.offer(row),true);assert.equal(snapshot(h),before);assert.equal(JSON.stringify(row),input);assert.equal(h.deck.size,1);return h.doc.body.textContent;}
for(const n of [0,1,2])test(`first arrival explains ${n} of two distinct existing work families through actual graph and PromptDeck`,()=>{const h=harness();try{if(n===0)clear(h);if(n===1)h.state.towlineTable=freshTowlineTable();const row=h.graph.readout(),text=show(h,row);assert.equal(row.evidence.families.length,n);assert.match(text,new RegExp('Recorded: '+n+' of 2 distinct work families'));if(n<2){for(const name of ['Tally Three','Ilex Ark','Towline Table','Last Shift'])assert(text.includes(name));assert(!text.includes('HELP RESTORE THE MILE'));assert.match(text,/different|other|Any two/);}else assert(text.includes('HELP RESTORE THE MILE'));assert.equal(h.deck.choose(ID,'leave','test'),true);assert.deepEqual(h.commands,[]);}finally{h.close()}});
test('multiple authentic Towline receipts count as one family, not receipt IDs',()=>{const h=harness();try{delete h.state.salvage.sources[TALLY_THREE.sourceKey];for(const id of ['mara','odo'])if(h.state.towlineTable.members[id])Object.assign(h.state.towlineTable.members[id].source,{status:'cleared',receipt:{id:towlineReceiptId(id),sourceId:towlineCleanupId(id),memberId:id,stationId:'station_ceres',by:'player',at:1}});const row=h.graph.readout();assert.deepEqual(row.evidence.families,['towline']);assert.equal(row.evidence.receiptIds.length,2);row.evidence.receiptIds=['duplicate','duplicate','unrelated'];assert.match(show(h,row),/Recorded: 1 of 2 distinct work families/);}finally{h.close()}});
test('duplicate recognized readout families do not invent a second work family',()=>{const h=harness();try{const row=h.graph.readout();row.canAccept=false;row.evidence={families:['tally','tally'],receiptIds:['x','x'],eligible:false};const text=show(h,row);assert.match(text,/Recorded: 1 of 2 distinct work families/);assert.match(text,/one other|different/);assert(!text.includes('HELP RESTORE THE MILE'));}finally{h.close()}});
for(const families of [undefined,null,'tally',['tally','tethys'],['tally',{}],Array(1)])test('malformed or unknown family readout requests a fresh scan, not another job: '+JSON.stringify(families),()=>{const h=harness();try{const row=h.graph.readout();row.canAccept=false;row.evidence={families,eligible:true};const text=show(h,row);assert.match(text,/record.*refresh|record.*check/i);assert.match(text,/scan/i);assert(!/one other|two more|Complete two|Any two/.test(text));assert(!text.includes('tethys'));}finally{h.close()}});
test('eligible but distant or stale acceptance does not claim another intervention is needed',()=>{const h=harness();try{h.state.entities.get(h.state.playerId).pos.x+=1000;const row=h.graph.readout();assert.equal(row.canAccept,false);assert.equal(row.evidence.eligible,true);row.lastResult={ok:false,reason:'two-verified-interventions-required'};const text=show(h,row);assert.match(text,/Recorded: 2 of 2 distinct work families/);assert.match(text,/scan/i);assert(!/Complete two|two qualifying|one other|Any two/.test(text));}finally{h.close()}});
test('settled Ilex with no surviving vaults counts honestly without claiming delivery success',()=>{const h=harness();try{clear(h);const row=freshIlexArk();row.phase='settled';row.settlement={id:ILEX_ARK.id+':outcome',stationId:ILEX_ARK.stationId,deliveredVaultIds:[],at:10,harvestAt:10+ILEX_ARK.harvestDelayS,rewardCr:0};h.state.ilexArk=row;const readout=h.graph.readout();assert.deepEqual(readout.evidence.families,['ilex']);assert.equal(readout.evidence.survivingVaults,0);const text=show(h,readout);assert.match(text,/Recorded: 1 of 2 distinct work families/);assert.match(text,/Ilex Ark settlement/);assert(!/successful Ilex|deliver.*vault|vaults saved/i.test(text));}finally{h.close()}});
test('accepted and pending work keeps existing chapter guidance, not prerequisite errands',()=>{const h=harness();try{assert(h.graph.accept(h.graph.readout().revision).ok);let row=h.graph.readout();let text=show(h,row);assert.match(text,/0 of 5 milestones/);assert(!text.includes('distinct work families'));h.prompt.newGame();row={...row,completedMilestoneIds:['survey'],pendingInstall:{receiptId:'fixture-pending'}};text=show(h,row);assert.match(text,/Installation is waiting for a clear socket/);assert(!text.includes('Any two'));}finally{h.close()}});

test('partial Ilex settlement records its family without demanding all vaults',()=>{const h=harness();try{clear(h);const row=freshIlexArk(),id=ILEX_VAULT_IDS[0];row.phase='settled';row.vaults[id].status='delivered';row.settlement={id:ILEX_ARK.id+':outcome',stationId:ILEX_ARK.stationId,deliveredVaultIds:[id],at:10,harvestAt:10+ILEX_ARK.harvestDelayS,rewardCr:ILEX_ARK.baseRewardCr+ILEX_ARK.vaultRewardCr};h.state.ilexArk=row;const readout=h.graph.readout();assert.deepEqual(readout.evidence.families,['ilex']);assert.equal(readout.evidence.survivingVaults,1);assert.match(show(h,readout),/Recorded: 1 of 2 distinct work families: Ilex Ark settlement/);}finally{h.close()}});
test('explicit stale work order never invents a missing prerequisite task',()=>{const h=harness();try{h.state.towlineTable=freshTowlineTable();const row=h.graph.readout();row.lastResult={ok:false,reason:'stale-revision'};const text=show(h,row);assert.match(text,/refresh the work order/);assert(!text.includes('Choose one other family'));}finally{h.close()}});
